function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (!Number.isInteger(k) || k < 0 || k > s.length) return 'k is an integer from 0 to s.length.';
  return null;
}

