function getLengthOfOptimalCompression(s, k) {
  const n = s.length;
  const encodedLength = (count) => (count === 1 ? 1 : count < 10 ? 2 : count < 100 ? 3 : 4);
  const dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(0));

  for (let i = n - 1; i >= 0; i--) {
    for (let budget = 0; budget <= k; budget++) {
      let best = budget > 0 ? dp[i + 1][budget - 1] : Infinity;
      let same = 0;
      let removed = 0;
      for (let j = i; j < n; j++) {
        if (s[j] === s[i]) {
          same++;
        } else {
          removed++;
        }
        if (removed > budget) {
          break;
        }
        best = Math.min(best, encodedLength(same) + dp[j + 1][budget - removed]);
      }
      dp[i][budget] = best;
    }
  }
  return dp[0][k];
}

