function getLengthOfOptimalCompression(s, k) {
  // Scan left to right remembering the open block (its letter and size); closed blocks are paid for when they end.
  const blockCost = (count) => (count === 0 ? 0 : count === 1 ? 1 : 1 + String(count).length);
  const memo = new Map();
  const solve = (i, letter, count, left) => {
    if (i === s.length) return blockCost(count);
    const key = i + ',' + letter + ',' + count + ',' + left;
    if (memo.has(key)) return memo.get(key);
    let result = s[i] === letter
      ? solve(i + 1, letter, count + 1, left)
      : blockCost(count) + solve(i + 1, s[i], 1, left);
    if (left > 0) result = Math.min(result, solve(i + 1, letter, count, left - 1));
    memo.set(key, result);
    return result;
  };
  return solve(0, '', 0, k);
}

