function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pick = (count) => letters.slice(0, count);
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 12);
    const alphabet = pick(1 + Math.floor(rand() * 3));
    let s = '';
    while (s.length < n) {
      const ch = alphabet[Math.floor(rand() * alphabet.length)];
      const run = 1 + Math.floor(rand() * 4);
      s += ch.repeat(run);
    }
    s = s.slice(0, n);
    return [s, Math.floor(rand() * (n + 1))];
  }
  const n = 80 + Math.floor(rand() * 21);
  const alphabet = pick(1 + Math.floor(rand() * 4));
  const longRuns = rand() < 0.5;
  let s = '';
  while (s.length < n) {
    const ch = alphabet[Math.floor(rand() * alphabet.length)];
    const run = longRuns ? 1 + Math.floor(rand() * 15) : 1 + Math.floor(rand() * 3);
    s += ch.repeat(run);
  }
  s = s.slice(0, n);
  return [s, Math.floor(rand() * rand() * (n + 1))];
}
